def greedy(w,k=4):
    d=lib(w); keys=list(d); sel=[]
    for _ in range(k):
        bestr=None
        for kk in keys:
            if kk in sel: continue
            A=np.column_stack([d[s] for s in sel+[kk]])
            c=np.linalg.lstsq(A,dv_dt,rcond=None)[0]
            r=np.sum((A@c-dv_dt)**2)
            if bestr is None or r<bestr[0]: bestr=(r,kk,c)
        sel.append(bestr[1])
    return bestr[0]/np.sum((dv_dt-dv_dt.mean())**2),sel,bestr[2].round(4)
